      const started = {state, attest: technical => technical, verify: () => ({fixture_execution_only: true}), installed: () => ({sha: pin.reviewer_sha, digest: pin.reviewer_digest, clean: true}),
        cacheRoot: cache, execute: f.execute, available: () => true};
