const assert = require('node:assert/strict');
const {readLocalConfig} = require('./local-git.cjs');

const base = {version: 1, base_branch: 'main', readme: 'README.md', repository_policy: 'AGENTS.md', verification: [['npm', 'test']],
  coverage: {format: 'istanbul', report: 'coverage.json', source_directory: 'src'}};
test('review_reuse is optional and, when set, only "outcome"', () => {
  assert.equal(readLocalConfig(base), base);
  assert.equal(readLocalConfig({...base, review_reuse: 'outcome'}).review_reuse, 'outcome');
  for (const value of ['exact', '', true, null, 1]) {
    assert.throws(() => readLocalConfig({...base, review_reuse: value}), /review_reuse must be "outcome"/, JSON.stringify(value));
  }
});

  const raw = JSON.stringify({role: task.role, phase: task.phase, schema: task.schema, text: task.prompt.slice(0, cut), packet});
  if (raw.includes(PREFIX)) return null;
  return digest({version: VERSION, semantics, ...(outcome ? {keying: 'outcome'} : {}), body: replace(raw, subs, 0, 1)});
}

// `literals()` gives the values of this run when a call is made: the digest of a snapshot changes when a source request
// adds evidence, so it is read per call. `read` turns reuse on; recording happens either way.
function createReuse({directory, read = false, semantics, literals, outcome = false}) {
  const pending = new Map();
  const stats = {reused: 0};
  const subsOf = () => {
    const {base, head, digests} = literals();
    return [[base, token('base')], [head, token('head')], ...digests.map((value, index) => [value, token(`digest-${index}`)])];
  };
  const file = key => path.join(directory, `${key}.json`);

  const load = (key, subs) => {
    try {
      const stored = JSON.parse(fs.readFileSync(file(key), 'utf8'));
      if (stored.version !== VERSION || stored.key !== key) return null;
      return JSON.parse(replace(stored.response, subs, 1, 0));
    } catch {
      return null;
    }
  };

  const wrap = ask => async task => {
    const subs = subsOf();
    const key = keyOf(task, {subs, semantics, outcome});
    if (key !== null && read) {
      const hit = load(key, subs);
      if (hit !== null) {
        try {
          task.check?.(hit.value);
          stats.reused++;
          return hit;
        } catch {
          // An answer that no longer validates against the new snapshot is not used; the reviewer is asked again.
        }
      }

  const split = Object.hasOwn(record, 'partition') && Buffer.byteLength(JSON.stringify(record)) > RECORD_LIMIT ? splitRecord(record) : null;
  const payload = {type: DOMAIN, key_id: keyId, issuer, reviewer_sha: reviewerSha, reviewer_digest: reviewerDigest,
    // Optional signed claim of the issuing engine's review semantics (review-semantics.cjs). Receipts without it are
    // accepted only under the exact engine, as before.
    ...(reviewerSemantics === undefined ? {} : {reviewer_semantics: reviewerSemantics}),
    // Optional signed claim that a maintainer reviewed someone else's pull request: it names the signer, the exact
    // pull request author and the pull request number. Receipts without it are bound to the signer's own login, as before.
    ...(attestation === undefined ? {} : {attestation}),
    // Optional signed claim that the review took stored answers under outcome keying (review-reuse.cjs): how many of its
    // reviewer calls were reused and how many were asked. Receipts without it reused none, or used the exact keying of a refresh.
    ...(reviewReuse === undefined ? {} : {review_reuse: reviewReuse}),
    issued_at: Math.floor(now / 1000), expires_at: Math.floor(now / 1000) + lifetime,
    nonce, record_digest: digest(record), record: split ? split.root : record};
  const signature = crypto.sign(null, Buffer.from(`${DOMAIN}\0${digest(payload)}`), key).toString('base64url');
  return split ? {payload, signature, parts: split.parts.map(part => part.toString('base64'))} : {payload, signature};
}

// The enrolled key that signed this envelope, or a refusal. It looks at the signed payload only, never at a record or a
// part, so it can run before anything else is fetched.
function signingKey(bundle, trust) {
  // The parts of a multi-part receipt travel beside the signed envelope; each is bounded like a receipt artifact.
  const keyList = bundle && typeof bundle === 'object' ? Object.keys(bundle).sort().join(',') : '';
  reject(['payload,signature', 'parts,payload,signature'].includes(keyList) &&
    typeof bundle.signature === 'string' && /^[a-zA-Z0-9_-]{86}$/.test(bundle.signature) &&
    Buffer.byteLength(JSON.stringify({payload: bundle.payload, signature: bundle.signature})) <= MAX_RECEIPT_BYTES, 'malformed signature envelope', 'malformed');
  const p = bundle.payload;
  const fields = 'expires_at,issued_at,issuer,key_id,nonce,record,record_digest,reviewer_digest,reviewer_sha,type';
  reject(p && Object.keys(p).filter(name => !['attestation', 'reviewer_semantics', 'review_reuse'].includes(name)).sort().join(',') === fields &&
    p.type === DOMAIN && (!Object.hasOwn(p, 'reviewer_semantics') || /^[a-f0-9]{64}$/.test(p.reviewer_semantics)) &&
    (!Object.hasOwn(p, 'review_reuse') || reuseClaim(p.review_reuse)),
  'unknown receipt type or fields', 'malformed');
  const key = trust.keys.find(item => item.id === p.key_id && item.issuer === p.issuer && !item.revoked);
  reject(key && crypto.verify(null, Buffer.from(`${DOMAIN}\0${digest(p)}`), key.public_key,
    Buffer.from(bundle.signature, 'base64url')), 'untrusted, revoked or invalid signature', 'signature');
  return key;
